export const MODEL = {
  /** Meshopt-compressed + texture-optimised copy of the supplied Sketchfab model (6 MB vs 42 MB). */
  bike: '/assets/model/mt09.glb',
  /** Original, untouched download — kept for reference, never loaded by the site. */
  original: '/assets/2025_yamaha_mt-09_sp_v4.glb',
} as const;

export type PictureId = 'shutterOff' | 'shutterOn' | 'front' | 'side' | 'threeQuarter' | 'brutalist' | 'coastal' | 'blackStudio';

export type Picture = {
  id: PictureId;
  /** Folder/filename stem inside /assets/img */
  stem: string;
  /** Native pixel size of the supplied render (used for aspect ratios + crop maths). */
  w: number;
  h: number;
  /** Widths that exist on disk. Last entry is the native size. */
  widths: number[];
  alt: string;
};

