export const pictureSrc = (p: Picture, width = p.w) => `/assets/img/${p.stem}-${width}.webp`;
export const pictureSrcSet = (p: Picture) =>
  p.widths.map((w) => `${pictureSrc(p, w)} ${w}w`).join(', ');

/**
 * Crop rectangles, in fractions (0–1) of the SOURCE image: [x, y, w, h].
 * A crop is never a new file — the same render is reused and framed in CSS,
 * so the motorcycle stays 100 % consistent everywhere.
 * Tweak a number here and the layout + its labels move together.
 */
export type Crop = readonly [x: number, y: number, w: number, h: number];

