/**
 * Cinematic environments (section 07).
 * Only renders that actually exist are enabled. NIGHT CITY and MOUNTAIN ROAD are still
 * open slots — when you have those renders, drop them in
 * /public/assets, add them to scripts/optimize-images.mjs + PICTURES above, then
 * flip the matching entry below (`picture` + `enabled: true`).
 */
export type EnvironmentScene = {
  id: string;
  enabled: boolean;
  title: string;
  kicker: string;
  caption: string;
  picture: PictureId | null;
  crop: Crop;
  /** object-position for cover-fitting, keeps the bike framed on every aspect ratio */
  focus: string;
  /** where the title sits so it never covers the machine: bottom-left, top-left, top-right */
  copy: 'bl' | 'tl' | 'tr';
};

